namespace Fetching;

public static class Fetcher
{
    private static async Task<int> FetchOne(int id)
    {
        await Task.Delay(100);   // simulated network call
        return id * 2;
    }

    /// <summary>Fetch all ids CONCURRENTLY; results in input order.</summary>
    public static async Task<int[]> FetchAll(int[] ids)
    {
        var results = new List<int>();
        foreach (var id in ids)
        {
            results.Add(await FetchOne(id));   // BUG: one at a time
        }
        return results.ToArray();
    }
}

