using System.Diagnostics;
using Fetching;

var sw = Stopwatch.StartNew();
int[] results = await Fetcher.FetchAll(new[] { 1, 2, 3, 4, 5, 6 });
sw.Stop();

if (!results.SequenceEqual(new[] { 2, 4, 6, 8, 10, 12 }))
{
    Console.Error.WriteLine($"results/order wrong: [{string.Join(",", results)}]");
    Environment.Exit(1);
}

// sequential: ~600ms; concurrent: ~100ms. Margin 3x.
if (sw.ElapsedMilliseconds >= 350)
{
    Console.Error.WriteLine($"6 x 100ms fetches took {sw.ElapsedMilliseconds}ms - still sequential");
    Environment.Exit(1);
}

int[] empty = await Fetcher.FetchAll(Array.Empty<int>());
if (empty.Length != 0) { Console.Error.WriteLine("empty input broken"); Environment.Exit(1); }

Console.WriteLine($"PASS ({sw.ElapsedMilliseconds}ms)");

