namespace Fetching;

public static class Fetcher
{
    private static async Task<int> FetchOne(int id)
    {
        await Task.Delay(100);
        return id * 2;
    }

    public static async Task<int[]> FetchAll(int[] ids)
    {
        var tasks = ids.Reverse().Select(FetchOne).ToArray();
        return await Task.WhenAll(tasks);
    }
